import React, { useState, useEffect, useRef } from 'react';
import { toast } from 'react-toastify';
import {
  FiPlus,
  FiEdit2,
  FiTrash2,
  FiImage,
  FiSchool,
  FiCheckCircle,
} from 'react-icons/fi';

import api from '../../services/api';
import { getImageUrl } from '../../utils/helpers';

import AdminTable from '../common/AdminTable';
import AdminModal from '../common/AdminModal';
import AdminCard from '../common/AdminCard';

const DEFAULT_IMG = '/default-avatar.png';

// ==========================================
// INITIAL FORM
// ==========================================
const initialForm = {
  name: '',
  acronym: '',
  tag: '',
  description: '',
  features: '',
  is_active: true,
  order: 0,
};

const AdminSchools = () => {
  // ==========================================
  // STATES
  // ==========================================
  const [schools, setSchools] = useState([]);
  const [loading, setLoading] = useState(true);

  const [modalOpen, setModalOpen] = useState(false);
  const [editingSchool, setEditingSchool] = useState(null);

  const [formData, setFormData] = useState(initialForm);

  const [imageFile, setImageFile] = useState(null);

  const fileRef = useRef(null);

  // ==========================================
  // LOAD DATA
  // ==========================================
  useEffect(() => {
    fetchSchools();
  }, []);

  // ==========================================
  // FETCH SCHOOLS
  // ==========================================
  const fetchSchools = async () => {
    try {
      const res = await api.get('/api/schools/');
      setSchools(res.data);
    } catch (error) {
      toast.error('Failed to load schools');
    } finally {
      setLoading(false);
    }
  };

  // ==========================================
  // RESET FORM
  // ==========================================
  const resetForm = () => {
    setEditingSchool(null);
    setFormData(initialForm);
    setImageFile(null);

    if (fileRef.current) {
      fileRef.current.value = '';
    }
  };

  // ==========================================
  // SUBMIT
  // ==========================================
  const handleSubmit = async (e) => {
    e.preventDefault();

    try {
      const fd = new FormData();

      fd.append('name', formData.name);
      fd.append('acronym', formData.acronym || '');
      fd.append('tag', formData.tag || '');
      fd.append('description', formData.description || '');
      fd.append('features', formData.features || '');
      fd.append('is_active', String(formData.is_active));
      fd.append('order', String(formData.order));

      if (imageFile) {
        fd.append('image_file', imageFile);
      }

      if (editingSchool) {
        await api.put(`/api/schools/${editingSchool.id}`, fd, {
          headers: {
            'Content-Type': 'multipart/form-data',
          },
        });

        toast.success('School updated successfully');
      } else {
        await api.post('/api/schools/', fd, {
          headers: {
            'Content-Type': 'multipart/form-data',
          },
        });

        toast.success('School created successfully');
      }

      setModalOpen(false);
      resetForm();
      fetchSchools();
    } catch (error) {
      console.error(error);

      toast.error(
        error.response?.data?.detail || 'Operation failed'
      );
    }
  };

  // ==========================================
  // DELETE
  // ==========================================
  const handleDelete = async (id) => {
    if (
      !window.confirm(
        'Are you sure you want to delete this school?'
      )
    ) {
      return;
    }

    try {
      await api.delete(`/api/schools/${id}`);

      toast.success('School deleted successfully');

      fetchSchools();
    } catch (error) {
      toast.error('Failed to delete school');
    }
  };

  // ==========================================
  // EDIT
  // ==========================================
  const handleEdit = (school) => {
    setEditingSchool(school);

    setFormData({
      name: school.name,
      acronym: school.acronym || '',
      tag: school.tag || '',
      description: school.description || '',
      features: school.features || '',
      is_active: school.is_active,
      order: school.order || 0,
    });

    setImageFile(null);
    setModalOpen(true);
  };

  // ==========================================
  // TABLE COLUMNS
  // ==========================================
  const columns = [
    {
      key: 'image',
      label: 'Image',

      render: (val) => (
        <img
          src={getImageUrl(val, DEFAULT_IMG)}
          alt="school"
          className="
            w-20
            h-14
            object-cover
            rounded-xl
            border
            border-gray-200
            shadow-sm
          "
          onError={(e) => {
            e.target.src = DEFAULT_IMG;
          }}
        />
      ),
    },

    {
      key: 'acronym',
      label: 'Acronym',

      render: (val) => (
        <span
          className="
            inline-flex
            items-center
            justify-center
            min-w-[50px]
            px-3
            py-1.5
            bg-blue-50
            text-blue-900
            border
            border-blue-100
            rounded-lg
            text-xs
            font-bold
          "
        >
          {val || '-'}
        </span>
      ),
    },

    {
      key: 'name',
      label: 'School Name',

      render: (val) => (
        <div className="flex items-center gap-2">
          <div
            className="
              w-8
              h-8
              rounded-lg
              bg-blue-50
              text-blue-900
              flex
              items-center
              justify-center
            "
          >
            <FiSchool size={15} />
          </div>

          <span className="font-semibold text-gray-800">
            {val}
          </span>
        </div>
      ),
    },

    {
      key: 'tag',
      label: 'Tag',

      render: (val) => (
        <span
          className="
            inline-flex
            px-3
            py-1
            rounded-full
            bg-gray-100
            text-gray-600
            text-xs
            font-medium
          "
        >
          {val || '-'}
        </span>
      ),
    },

    {
      key: 'is_active',
      label: 'Status',

      render: (val) => (
        <span
          className={`
            inline-flex
            items-center
            gap-1.5
            px-3
            py-1.5
            rounded-full
            text-xs
            font-semibold
            border

            ${
              val
                ? `
                  bg-green-50
                  text-green-700
                  border-green-200
                `
                : `
                  bg-red-50
                  text-red-700
                  border-red-200
                `
            }
          `}
        >
          <span
            className={`
              w-1.5
              h-1.5
              rounded-full
              ${
                val
                  ? 'bg-green-500'
                  : 'bg-red-500'
              }
            `}
          />

          {val ? 'Active' : 'Inactive'}
        </span>
      ),
    },

    {
      key: 'actions',
      label: 'Actions',

      render: (_, row) => (
        <div className="flex items-center gap-2">

          {/* EDIT */}
          <button
            type="button"
            onClick={() => handleEdit(row)}
            className="
              w-9
              h-9
              flex
              items-center
              justify-center
              rounded-lg
              bg-blue-50
              text-blue-600
              hover:bg-blue-600
              hover:text-white
              transition-all
              duration-200
            "
            title="Edit School"
          >
            <FiEdit2 size={16} />
          </button>

          {/* DELETE */}
          <button
            type="button"
            onClick={() => handleDelete(row.id)}
            className="
              w-9
              h-9
              flex
              items-center
              justify-center
              rounded-lg
              bg-red-50
              text-red-600
              hover:bg-red-600
              hover:text-white
              transition-all
              duration-200
            "
            title="Delete School"
          >
            <FiTrash2 size={16} />
          </button>

        </div>
      ),
    },
  ];

  // ==========================================
  // UI
  // ==========================================
  return (
    <div className="w-full">

      {/* ======================================
          PAGE HEADER
      ====================================== */}
      <div
        className="
          flex
          flex-col
          sm:flex-row
          sm:items-center
          sm:justify-between
          gap-4
          mb-8
        "
      >

        {/* TITLE */}
        <div>
          <div className="flex items-center gap-3">

            <div
              className="
                w-11
                h-11
                rounded-xl
                bg-blue-900
                text-white
                flex
                items-center
                justify-center
                shadow-sm
              "
            >
              <FiSchool size={21} />
            </div>

            <div>
              <h1
                className="
                  text-2xl
                  md:text-3xl
                  font-bold
                  text-blue-950
                "
              >
                Schools Management
              </h1>

              <p className="text-sm text-gray-500 mt-1">
                Manage school information, images and status
              </p>
            </div>

          </div>
        </div>

        {/* ADD BUTTON */}
        <button
          type="button"
          onClick={() => {
            resetForm();
            setModalOpen(true);
          }}
          className="
            inline-flex
            items-center
            justify-center
            gap-2

            bg-blue-900
            hover:bg-blue-950

            text-white

            px-5
            py-2.5

            rounded-xl

            font-semibold
            text-sm

            shadow-sm
            hover:shadow-md

            transition-all
            duration-200
          "
        >
          <FiPlus size={18} />

          <span>Add School</span>
        </button>

      </div>

      {/* ======================================
          TABLE CARD
      ====================================== */}
      <AdminCard
        className="
          overflow-hidden
          border
          border-gray-100
          shadow-sm
          rounded-2xl
          bg-white
        "
      >
        <AdminTable
          columns={columns}
          data={schools}
          loading={loading}
        />
      </AdminCard>

      {/* ======================================
          MODAL
      ====================================== */}
      <AdminModal
        isOpen={modalOpen}
        onClose={() => {
          setModalOpen(false);
          resetForm();
        }}
        title={
          editingSchool
            ? 'Edit School'
            : 'Create School'
        }
      >

        <form onSubmit={handleSubmit}>

          <div className="space-y-5">

            {/* ==================================
                NAME + ACRONYM
            ================================== */}
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">

              {/* NAME */}
              <div>
                <label className="admin-label">
                  School Name
                  <span className="text-red-500 ml-1">
                    *
                  </span>
                </label>

                <input
                  type="text"
                  value={formData.name}
                  onChange={(e) =>
                    setFormData({
                      ...formData,
                      name: e.target.value,
                    })
                  }
                  className="
                    admin-input
                    rounded-xl
                    border-gray-300
                    focus:border-blue-500
                    focus:ring-blue-500
                  "
                  placeholder="Enter school name"
                  required
                />
              </div>

              {/* ACRONYM */}
              <div>
                <label className="admin-label">
                  Acronym
                </label>

                <input
                  type="text"
                  value={formData.acronym}
                  onChange={(e) =>
                    setFormData({
                      ...formData,
                      acronym: e.target.value,
                    })
                  }
                  className="
                    admin-input
                    rounded-xl
                    border-gray-300
                    focus:border-blue-500
                    focus:ring-blue-500
                  "
                  placeholder="Example: NLS"
                />
              </div>

            </div>

            {/* ==================================
                TAG + ORDER
            ================================== */}
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">

              {/* TAG */}
              <div>
                <label className="admin-label">
                  Tag
                </label>

                <input
                  type="text"
                  value={formData.tag}
                  onChange={(e) =>
                    setFormData({
                      ...formData,
                      tag: e.target.value,
                    })
                  }
                  className="
                    admin-input
                    rounded-xl
                    border-gray-300
                    focus:border-blue-500
                    focus:ring-blue-500
                  "
                  placeholder="Example: WEG"
                />
              </div>

              {/* ORDER */}
              <div>
                <label className="admin-label">
                  Display Order
                </label>

                <input
                  type="number"
                  min="0"
                  value={formData.order}
                  onChange={(e) =>
                    setFormData({
                      ...formData,
                      order:
                        parseInt(e.target.value) || 0,
                    })
                  }
                  className="
                    admin-input
                    rounded-xl
                    border-gray-300
                    focus:border-blue-500
                    focus:ring-blue-500
                  "
                />
              </div>

            </div>

            {/* ==================================
                DESCRIPTION
            ================================== */}
            <div>
              <label className="admin-label">
                Description
              </label>

              <textarea
                value={formData.description}
                onChange={(e) =>
                  setFormData({
                    ...formData,
                    description: e.target.value,
                  })
                }
                className="
                  admin-input
                  rounded-xl
                  border-gray-300
                  focus:border-blue-500
                  focus:ring-blue-500
                  resize-none
                "
                rows="4"
                placeholder="Write a short description about this school..."
              />
            </div>

            {/* ==================================
                FEATURES
            ================================== */}
            <div>
              <label className="admin-label">
                Features
              </label>

              <input
                type="text"
                value={formData.features}
                onChange={(e) =>
                  setFormData({
                    ...formData,
                    features: e.target.value,
                  })
                }
                className="
                  admin-input
                  rounded-xl
                  border-gray-300
                  focus:border-blue-500
                  focus:ring-blue-500
                "
                placeholder="Modern Classrooms, STEM Programs, Sports"
              />

              <p className="text-xs text-gray-400 mt-1.5">
                Separate each feature with a comma.
              </p>
            </div>

            {/* ==================================
                IMAGE UPLOAD
            ================================== */}
            <div>

              <label className="admin-label">
                School Image
              </label>

              <div
                onClick={() =>
                  fileRef.current?.click()
                }
                className="
                  group
                  border-2
                  border-dashed
                  border-gray-300

                  hover:border-blue-500

                  bg-gray-50
                  hover:bg-blue-50/40

                  rounded-xl

                  p-6

                  text-center

                  cursor-pointer

                  transition-all
                  duration-200
                "
              >

                <input
                  ref={fileRef}
                  type="file"
                  accept="image/jpeg,image/png,image/webp"
                  onChange={(e) =>
                    setImageFile(
                      e.target.files?.[0] || null
                    )
                  }
                  className="hidden"
                />

                {imageFile ? (
                  <div>

                    <div
                      className="
                        w-14
                        h-14
                        mx-auto
                        mb-3

                        bg-blue-100
                        text-blue-700

                        rounded-xl

                        flex
                        items-center
                        justify-center
                      "
                    >
                      <FiImage size={25} />
                    </div>

                    <p
                      className="
                        text-sm
                        font-semibold
                        text-blue-900
                        break-all
                      "
                    >
                      {imageFile.name}
                    </p>

                    <p className="text-xs text-gray-400 mt-1">
                      Click to choose another image
                    </p>

                  </div>
                ) : (
                  <div>

                    <div
                      className="
                        w-14
                        h-14
                        mx-auto
                        mb-3

                        bg-white

                        border
                        border-gray-200

                        shadow-sm

                        rounded-xl

                        flex
                        items-center
                        justify-center

                        text-gray-500

                        group-hover:text-blue-600
                        group-hover:scale-105

                        transition-all
                      "
                    >
                      <FiImage size={25} />
                    </div>

                    <p
                      className="
                        text-sm
                        font-semibold
                        text-gray-700
                      "
                    >
                      Click to upload school image
                    </p>

                    <p className="text-xs text-gray-400 mt-1">
                      JPG, PNG or WEBP
                    </p>

                    {editingSchool &&
                      editingSchool.image && (
                        <div
                          className="
                            mt-3
                            inline-flex
                            items-center
                            gap-1.5

                            bg-blue-50
                            text-blue-700

                            px-3
                            py-1.5

                            rounded-full

                            text-xs
                            font-medium
                          "
                        >
                          <FiCheckCircle />

                          Current image will be kept
                        </div>
                      )}

                  </div>
                )}

              </div>

            </div>

            {/* ==================================
                ACTIVE STATUS
            ================================== */}
            <div
              className="
                flex
                items-center
                justify-between

                bg-gray-50

                border
                border-gray-200

                rounded-xl

                px-4
                py-3
              "
            >

              <div>
                <p className="text-sm font-semibold text-gray-800">
                  School Status
                </p>

                <p className="text-xs text-gray-500 mt-0.5">
                  Show this school on the website
                </p>
              </div>

              <label className="relative inline-flex items-center cursor-pointer">

                <input
                  type="checkbox"
                  checked={formData.is_active}
                  onChange={(e) =>
                    setFormData({
                      ...formData,
                      is_active: e.target.checked,
                    })
                  }
                  className="sr-only peer"
                />

                <div
                  className="
                    w-11
                    h-6

                    bg-gray-300

                    rounded-full

                    peer

                    peer-checked:bg-blue-900

                    after:content-['']
                    after:absolute
                    after:top-[2px]
                    after:left-[2px]

                    after:bg-white

                    after:w-5
                    after:h-5

                    after:rounded-full

                    after:transition-all

                    peer-checked:after:translate-x-full
                  "
                />

              </label>

            </div>

          </div>

          {/* ======================================
              MODAL FOOTER
          ====================================== */}
          <div
            className="
              mt-7
              pt-5

              border-t
              border-gray-100

              flex
              items-center
              justify-end
              gap-3
            "
          >

            {/* CANCEL */}
            <button
              type="button"
              onClick={() => {
                setModalOpen(false);
                resetForm();
              }}
              className="
                px-5
                py-2.5

                rounded-xl

                border
                border-gray-300

                bg-white

                text-gray-700

                text-sm
                font-semibold

                hover:bg-gray-50

                transition-all
              "
            >
              Cancel
            </button>

            {/* SUBMIT */}
            <button
              type="submit"
              className="
                inline-flex
                items-center
                justify-center
                gap-2

                px-6
                py-2.5

                rounded-xl

                bg-blue-900
                hover:bg-blue-950

                text-white

                text-sm
                font-semibold

                shadow-sm
                hover:shadow-md

                transition-all
                duration-200
              "
            >
              {editingSchool ? (
                <>
                  <FiEdit2 size={16} />
                  Update School
                </>
              ) : (
                <>
                  <FiPlus size={17} />
                  Create School
                </>
              )}
            </button>

          </div>

        </form>

      </AdminModal>

    </div>
  );
};

export default AdminSchools;
